def test_g1a_yolo_bbox_dict_of_ints(yolo26_detect_response):
    for det in yolo26_detect_response["detections"]:
        b = det["bbox"]
        assert set(b) == {"x", "y", "width", "height"}
        assert all(type(v) is int for v in b.values())          # ints, not floats
        assert b["x"] >= 0 and b["y"] >= 0                      # top-left origin, abs px
        assert b["x"] + b["width"] <= yolo26_detect_response["image_width"]  # in-frame
